package org.slavicmyths.verify;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.bogatyr.*;
import org.slavicmyths.bogatyr.BogatyrRules.State;

/** Dedicated-server tests with synthetic ServerPlayers, not real remote-client multiplayer. */
@GameTestHolder("slavicmyths_bogatyr") @PrefixGameTestTemplate(false)
public final class BogatyrGameTests {
    private static final class Connection extends net.minecraft.network.Connection {
        private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();
        Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public io.netty.channel.Channel channel(){return channel;}
    }
    private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {
        Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}
        @Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener l){}
    }
    @SuppressWarnings("unchecked") private static Map<UUID,ServerPlayer> online(ServerPlayer p){try{var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);return (Map<UUID,ServerPlayer>)f.get(p.server.getPlayerList());}catch(Exception e){throw new RuntimeException(e);}}
    private static ServerPlayer player(GameTestHelper t){var w=t.getLevel();var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"BogatyrTest"),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);try{var f=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(p,0);}catch(Exception e){throw new RuntimeException(e);}p.setNoGravity(true);p.moveTo(t.absoluteVec(new Vec3(16,2,18)));p.setOnGround(true);p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(24);p.setHealth(24);w.addNewPlayer(p);online(p).put(p.getUUID(),p);return p;}
    private static void diamond(ServerPlayer p){p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.DIAMOND_HELMET));p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.DIAMOND_CHESTPLATE));p.setItemSlot(EquipmentSlot.LEGS,new ItemStack(Items.DIAMOND_LEGGINGS));p.setItemSlot(EquipmentSlot.FEET,new ItemStack(Items.DIAMOND_BOOTS));p.doTick();if(p.getArmorValue()!=20)throw new AssertionError("Fixture armor not applied: "+p.getArmorValue());}
    private static void floor(GameTestHelper t){for(int x=0;x<32;x++)for(int z=0;z<32;z++)t.setBlock(new BlockPos(x,1,z),Blocks.STONE);}
    private static IdolishcheEntity boss(GameTestHelper t,ServerPlayer p){floor(t);var b=BogatyrContent.IDOL.get().create(t.getLevel());b.moveTo(t.absoluteVec(new Vec3(16,2,12)));t.getLevel().addFreshEntity(b);b.start(p,true);b.setTarget(p);b.face(p);b.begin(State.STUNNED,1000);return b;}
    private static IlyaEntity hero(GameTestHelper t,ServerPlayer p,IdolishcheEntity b){var h=BogatyrContent.ILYA.get().create(t.getLevel());h.owner=p.getUUID();h.moveTo(t.absoluteVec(new Vec3(16,2,17)));t.getLevel().addFreshEntity(h);var d=BogatyrLedger.get(t.getLevel());d.heroes.put(p.getUUID(),h.getUUID());d.setDirty();if(b!=null)h.bind(b);return h;}
    private static void clean(ServerPlayer p,Entity... mobs){online(p).remove(p.getUUID());var d=BogatyrLedger.get(p.serverLevel());d.heroes.remove(p.getUUID());d.victories.remove(p.getUUID());d.setDirty();p.discard();for(var e:mobs)e.discard();}
    private static void damage(GameTestHelper t,String attack,float raw,float min,float max){var p=player(t);diamond(p);var b=boss(t,p);float hp=p.getHealth();p.hurt(IdolishcheEntity.source(b,attack),raw);float net=hp-p.getHealth();System.out.println("BOGATYR_DIAMOND hit="+attack+" raw="+raw+" hpBefore="+hp+" hpAfter="+p.getHealth()+" net="+net);t.assertTrue(net>=min&&net<=max,attack+" net="+net);clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void registeredDimensions(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);t.assertTrue(h.getMaxHealth()==280&&b.getMaxHealth()==900,"Max HP");t.assertTrue(Math.abs(h.getBbWidth()-.93)<.001&&Math.abs(h.getBbHeight()-2.45)<.001,"Ilya dimensions");t.assertTrue(Math.abs(b.getBbWidth()-4.2)<.001&&Math.abs(b.getBbHeight()-8.8)<.001,"Idolishche dimensions");t.assertTrue(b.isMultipartEntity()&&b.getParts().length==2,"Wrist part");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void diamondFist(GameTestHelper t){damage(t,"fist",20,7.9F,8.1F);}
    @GameTest(template="empty",timeoutTicks=30) public static void diamondOuter(GameTestHelper t){damage(t,"stomp",20,7.9F,8.1F);}
    @GameTest(template="empty",timeoutTicks=30) public static void diamondMiddle(GameTestHelper t){damage(t,"stomp",22,9.2F,9.3F);}
    @GameTest(template="empty",timeoutTicks=30) public static void diamondInner(GameTestHelper t){damage(t,"stomp",26,11.9F,12.1F);}
    @GameTest(template="empty",timeoutTicks=30) public static void resistanceMatters(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE,100));p.hurt(IdolishcheEntity.source(b,"fist"),20);t.assertTrue(Math.abs(24-p.getHealth()-6.4)<.05,"Resistance bypassed");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void physicalPassive(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.hurt(p.damageSources().playerAttack(p),20);t.assertTrue(Math.abs(280-h.getHealth()-15)<.01,"25 percent passive");h.invulnerableTime=0;h.hurt(p.damageSources().playerAttack(p),20);t.assertTrue(Math.abs(280-h.getHealth()-30)<.01,"Passive stacks");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void magicUnmitigated(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.hurt(h.damageSources().magic(),20);t.assertTrue(Math.abs(280-h.getHealth()-20)<.01,"Magic treated physical");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void unyieldingMultiplicative(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.unyieldingUntil=t.getLevel().getGameTime()+200;h.hurt(p.damageSources().playerAttack(p),20);t.assertTrue(Math.abs(280-h.getHealth()-11.25)<.01,"Crisis reduction not .75*.75");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void shieldFront(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.face(p);h.begin(State.SHIELD_HOLD,64);h.hurt(p.damageSources().playerAttack(p),20);t.assertTrue(Math.abs(280-h.getHealth()-6)<.01,"Frontal shield reduction");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void shieldRear(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.face(p);h.setYRot(h.getYRot()+180);h.begin(State.SHIELD_HOLD,64);h.hurt(p.damageSources().playerAttack(p),20);t.assertTrue(Math.abs(280-h.getHealth()-15)<.01,"Rear shield immune");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void massiveShield(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.face(b);h.begin(State.SHIELD_HOLD,64);h.hurt(IdolishcheEntity.source(b,"stomp"),20);t.assertTrue(Math.abs(280-h.getHealth()-12)<.01,"Stomp fully blocked");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=100) public static void finiteShield(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.begin(State.SHIELD_HOLD,64);t.runAtTickTime(65,()->t.assertTrue(h.state()!=State.SHIELD_HOLD,"Infinite hold"));t.runAtTickTime(80,()->{t.assertTrue(!h.shield(),"Shield failed to recover");clean(p,h);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void shieldBreak(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.face(p);h.begin(State.SHIELD_HOLD,64);for(int i=0;i<3;i++){h.invulnerableTime=0;h.hurt(p.damageSources().playerAttack(p),20);}t.assertTrue(h.state()==State.SHIELD_RECOVER,"Three heavy blocks no break");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=55) public static void fistHasWindup(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);b.begin(State.FIST_WINDUP,22);t.runAtTickTime(21,()->t.assertTrue(p.getHealth()==24,"Early fist"));t.runAtTickTime(32,()->{t.assertTrue(p.getHealth()<18,"Fist missed hit frame net baseline");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=85) public static void stompOneHit(GameTestHelper t){var p=player(t);p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(100);p.setHealth(100);diamond(p);var b=boss(t,p);p.moveTo(b.getX(),b.getY(),b.getZ()+3);b.begin(State.STOMP_TELEGRAPH,32);t.runAtTickTime(31,()->t.assertTrue(p.getHealth()==100,"Early stomp"));t.runAtTickTime(39,()->p.moveTo(b.getX(),b.getY(),b.getZ()+8));t.runAtTickTime(46,()->p.moveTo(b.getX(),b.getY(),b.getZ()+13));t.runAtTickTime(54,()->{float net=100-p.getHealth();t.assertTrue(net>11.9&&net<12.1,"Multiple stomp zones hit "+net);clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=60) public static void stompEscape(GameTestHelper t){var p=player(t);var b=boss(t,p);p.moveTo(b.getX(),b.getY(),b.getZ()+17);b.begin(State.STOMP_TELEGRAPH,32);t.runAtTickTime(55,()->{t.assertTrue(p.getHealth()==24,"Stomp beyond R15");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=80) public static void rageOnce(GameTestHelper t){var p=player(t);var b=boss(t,p);b.setHealth(315);t.runAtTickTime(3,()->{t.assertTrue(b.rage()&&b.state()==State.RAGE_TRANSITION,"No 35pct phase");b.heal(45);});t.runAtTickTime(70,()->{t.assertTrue(b.rage()&&b.state()!=State.RAGE_TRANSITION,"Rage replay or reversed by feed");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void maceHitFrame(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setTarget(b);h.face(b);h.begin(State.MACE_WINDUP,31);h.cooldown("mace",500);h.cooldown("shield",500);t.runAtTickTime(17,()->t.assertTrue(b.getHealth()==900,"Mace damage before t19"));t.runAtTickTime(22,()->{t.assertTrue(b.getHealth()==890,"Mace not raw10 once at19: "+b.getHealth());clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void tauntFocus(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.begin(State.TAUNT_CAST,28);t.runAtTickTime(18,()->{t.assertTrue(b.getTarget()==h,"Taunt did not focus");t.assertTrue(!h.ready("taunt"),"Taunt cooldown missing");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void unyieldingOnce(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setHealth(84);t.runAtTickTime(3,()->t.assertTrue(h.unyieldingUsed&&h.state()==State.UNYIELDING,"Threshold84"));t.runAtTickTime(34,()->{long until=h.unyieldingUntil;h.setHealth(200);h.setHealth(84);h.tick();t.assertTrue(h.unyieldingUntil==until,"Crisis refreshed by healing");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=50) public static void summonMinions(GameTestHelper t){var p=player(t);var b=boss(t,p);b.begin(State.FEED_SUMMON,50);t.runAtTickTime(28,()->t.assertTrue(t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.monster.Zombie.class,b.getBoundingBox().inflate(12)).stream().noneMatch(z->z.getPersistentData().hasUUID("IdolOwner")),"Early summon"));t.runAtTickTime(34,()->{var zs=t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.monster.Zombie.class,b.getBoundingBox().inflate(12),z->z.getPersistentData().hasUUID("IdolOwner")&&z.getPersistentData().getUUID("IdolOwner").equals(b.getUUID()));t.assertTrue(zs.size()>=2&&zs.size()<=3,"Summon count "+zs.size());for(var z:zs)t.assertTrue(z.getPersistentData().getBoolean("feedEligible"),"Unmarked minion");b.reset();t.assertTrue(zs.stream().noneMatch(Entity::isAlive),"Reset leaves minions");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void progressParticipation(GameTestHelper t){var p=player(t);var b=boss(t,p);b.debug=false;b.contribution(p);b.die(p.damageSources().playerAttack(p));var d=BogatyrLedger.get(t.getLevel());var v=d.victories.get(p.getUUID());t.assertTrue(v!=null&&v.getBoolean("eligibleForFutureRewards")&&v.getInt("defeatCount")==1,"Victory not stored");t.assertTrue(t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,b.getBoundingBox().inflate(8)).isEmpty(),"Boss loot leaked");var loaded=BogatyrLedger.load(d.save(new CompoundTag(),t.getLevel().registryAccess()),t.getLevel().registryAccess());t.assertTrue(loaded.victories.get(p.getUUID()).equals(v),"Victory NBT roundtrip");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void debugNoVictory(GameTestHelper t){var p=player(t);var b=boss(t,p);b.contribution(p);b.die(p.damageSources().playerAttack(p));t.assertTrue(!BogatyrLedger.get(t.getLevel()).victories.containsKey(p.getUUID()),"Debug victory leak");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void duplicateAndMidfightCall(GameTestHelper t){var p=player(t);floor(t);t.assertTrue(BogatyrLedger.call(p),"Safe call failed");var h=BogatyrLedger.hero(p);t.assertTrue(!BogatyrLedger.call(p),"Duplicate call accepted");var b=boss(t,p);var other=player(t);t.assertTrue(!BogatyrLedger.call(other),"Midbattle call accepted");clean(other);clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void hurtCooldownSaved(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.cooldown("mace",420);h.unyieldingUsed=true;h.returned=true;var n=new CompoundTag();h.addAdditionalSaveData(n);h.readAdditionalSaveData(n);t.assertTrue(!h.ready("mace")&&h.unyieldingUsed&&h.returned&&h.owner.equals(p.getUUID()),"Reload resets cooldown/budget/owner");clean(p,h,b);t.succeed();}
    private static void field(Object o,String key,Object value){try{var f=o.getClass().getDeclaredField(key);f.setAccessible(true);f.set(o,value);}catch(Exception e){throw new RuntimeException(e);}}
    @SuppressWarnings("unchecked") private static net.minecraft.world.entity.monster.Zombie food(GameTestHelper t,IdolishcheEntity b){var z=EntityType.ZOMBIE.create(t.getLevel());z.moveTo(b.getX()+5,b.getY(),b.getZ());z.getPersistentData().putUUID("IdolOwner",b.getUUID());z.getPersistentData().putUUID("IdolEncounter",b.encounter);z.getPersistentData().putBoolean("feedEligible",true);z.setNoAi(true);t.getLevel().addFreshEntity(z);try{var f=IdolishcheEntity.class.getDeclaredField("minions");f.setAccessible(true);((Set<UUID>)f.get(b)).add(z.getUUID());}catch(Exception e){throw new RuntimeException(e);}field(b,"minion",z.getUUID());return z;}
    @GameTest(template="empty",timeoutTicks=70) public static void feedingHealsExactly45(GameTestHelper t){var p=player(t);var b=boss(t,p);b.setHealth(800);var z=food(t,b);b.begin(State.FEED_CHEW,52);t.runAtTickTime(39,()->t.assertTrue(b.getHealth()==800&&z.isAlive(),"Early swallow"));t.runAtTickTime(42,()->{t.assertTrue(b.getHealth()==845&&b.feeds==1&&!z.isAlive(),"Feed heal/charge/consumption");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=60) public static void feedingInterrupt(GameTestHelper t){var p=player(t);var b=boss(t,p);b.setHealth(800);var z=food(t,b);b.begin(State.FEED_CHEW,52);t.runAtTickTime(14,()->{b.hurt(p.damageSources().playerAttack(p),32);t.assertTrue(b.state()==State.STUNNED,"32 raw failed interrupt");});t.runAtTickTime(43,()->{t.assertTrue(b.getHealth()<=768&&b.feeds==0,"Interrupted feed healed");clean(p,z,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=45) public static void heroFeedInterrupt(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);b.setHealth(800);var z=food(t,b);b.begin(State.FEED_CHEW,52);h.begin(State.SHIELD_RECOVER,100);t.runAtTickTime(14,()->{b.heroMace(h);b.hurt(p.damageSources().playerAttack(p),8);t.assertTrue(b.state()==State.STUNNED&&b.feeds==0,"40 hero +8 player failed interrupt");clean(p,z,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=60) public static void feedingMaxTwo(GameTestHelper t){var p=player(t);var b=boss(t,p);b.setHealth(800);b.feeds=2;var z=food(t,b);b.begin(State.FEED_CHEW,52);t.runAtTickTime(42,()->{t.assertTrue(b.getHealth()==800&&b.feeds==2,"Third successful feed");clean(p,z,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=85) public static void minionCap(GameTestHelper t){var p=player(t);var b=boss(t,p);b.begin(State.FEED_SUMMON,50);t.runAtTickTime(34,()->b.begin(State.FEED_SUMMON,50));t.runAtTickTime(67,()->{var zs=t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.monster.Zombie.class,b.getBoundingBox().inflate(16),z->z.getPersistentData().hasUUID("IdolOwner")&&z.getPersistentData().getUUID("IdolOwner").equals(b.getUUID()));t.assertTrue(zs.size()>=4&&zs.size()<=5,"Minion cap "+zs.size());b.reset();clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=60) public static void handRescue(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);b.begin(State.GRAB_START,25);t.runAtTickTime(35,()->{t.assertTrue(b.grabbed(p),"Grab failed");b.rightHand.hurt(p.damageSources().playerAttack(p),25);});t.runAtTickTime(37,()->{t.assertTrue(!b.grabbed(p)&&b.state()==State.STUNNED,"Wrist25 did not rescue");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=60) public static void sixActionEscape(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);b.begin(State.GRAB_START,25);for(int tick:new int[]{34,37,40,43,46,49})t.runAtTickTime(tick,()->b.struggle(p));t.runAtTickTime(51,()->{t.assertTrue(p.isAlive()&&!b.grabbed(p),"Six timed actions did not escape");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void interceptExactlyOnce(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);var h=hero(t,p,b);h.face(b);h.begin(State.SHIELD_HOLD,64);p.hurt(IdolishcheEntity.source(b,"fist"),20);t.assertTrue(p.getHealth()==24&&Math.abs(h.getHealth()-274)<.01,"Intercept not redirected once");p.hurt(IdolishcheEntity.source(b,"fist"),20);t.assertTrue(Math.abs(p.getHealth()-16)<.01,"Intercept repeats indefinitely");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void aoeNotIntercepted(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);var h=hero(t,p,b);h.face(b);h.begin(State.SHIELD_HOLD,64);p.hurt(IdolishcheEntity.source(b,"stomp"),20);t.assertTrue(p.getHealth()==16&&h.getHealth()==280,"AOE redirected");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=85) public static void poisonBudgetAndDebuffs(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);b.begin(State.BREATH_WINDUP,25);t.runAtTickTime(24,()->t.assertTrue(p.getHealth()==24,"Early breath"));t.runAtTickTime(37,()->{t.assertTrue(p.hasEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN)&&p.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&p.hasEffect(net.minecraft.world.effect.MobEffects.CONFUSION),"Breath debuffs missing");t.assertTrue(p.getHealth()==16,"Initial breath net");});t.runAtTickTime(74,()->{t.assertTrue(p.getHealth()>=15&&p.getHealth()<=16,"Poison budget not 1/40ticks");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=90) public static void chargeLockedHeading(GameTestHelper t){var p=player(t);var b=boss(t,p);p.moveTo(b.getX(),b.getY(),b.getZ()+18);b.face(p);b.begin(State.CHARGE_WINDUP,28);float yaw=b.lockedYaw();t.runAtTickTime(29,()->p.moveTo(b.getX()+12,b.getY(),b.getZ()+10));t.runAtTickTime(45,()->t.assertTrue(Math.abs(b.getYRot()-yaw)<.01,"Charge homes after lock"));t.runAtTickTime(74,()->{t.assertTrue(b.state()==State.SHIELD_RECOVER||b.state()==State.STUNNED,"Charge no recovery");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=45) public static void returnBudget(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.returned=true;h.setHealth(140);h.recoveryEnd=t.getLevel().getGameTime()+5;h.begin(State.RECOVERY,5);t.runAtTickTime(7,()->{t.assertTrue(h.state()==State.DOWN_FOR_ENCOUNTER,"Second return allowed");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=50) public static void firstReturn(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setHealth(140);h.recoveryEnd=t.getLevel().getGameTime()+5;h.begin(State.RECOVERY,5);t.runAtTickTime(8,()->{t.assertTrue(h.returned&&h.state()==State.RETURNING,"First return blocked");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=45) public static void recoveryAfterBossDeath(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setHealth(140);h.recoveryEnd=t.getLevel().getGameTime()+5;h.begin(State.RECOVERY,5);b.die(p.damageSources().playerAttack(p));t.runAtTickTime(8,()->{t.assertTrue(h.bossId==null&&h.state()==State.RETURNING,"Recovery stuck after victory");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void spectatorNoProgress(GameTestHelper t){var p=player(t);var b=boss(t,p);b.debug=false;p.setGameMode(GameType.SPECTATOR);b.contribution(p);b.die(b.damageSources().generic());t.assertTrue(!BogatyrLedger.get(t.getLevel()).victories.containsKey(p.getUUID()),"Spectator awarded");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void bystanderNoProgress(GameTestHelper t){var p=player(t);var other=player(t);var b=boss(t,p);b.debug=false;b.contribution(p);b.die(p.damageSources().playerAttack(p));t.assertTrue(BogatyrLedger.get(t.getLevel()).victories.containsKey(p.getUUID())&&!BogatyrLedger.get(t.getLevel()).victories.containsKey(other.getUUID()),"Nearby nonparticipant awarded");clean(other);clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void allSoundsRegistered(GameTestHelper t){for(String who:List.of("ilya_muromets","idolishche_poganoe"))for(String cue:who.equals("ilya_muromets")?BogatyrContent.HERO_CUES:BogatyrContent.BOSS_CUES){var sound=BogatyrContent.sound(who,cue);t.assertTrue(net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.getKey(sound).equals(BogatyrContent.id(who+"."+cue)),"Sound not registered "+cue);}t.succeed();}
    @GameTest(template="empty",timeoutTicks=65) public static void timelyJumpReduction(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);p.moveTo(b.getX(),b.getY()+.6,b.getZ()+3);p.setOnGround(false);b.begin(State.STOMP_TELEGRAPH,32);t.runAtTickTime(38,()->{float net=24-p.getHealth();t.assertTrue(net>3.70&&net<3.72,"Jump reduction "+net);clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=95) public static void chargeWallStun(GameTestHelper t){var p=player(t);var b=boss(t,p);p.moveTo(b.getX(),b.getY(),b.getZ()+18);for(int x=-4;x<=4;x++)for(int y=0;y<10;y++)for(int z=7;z<=9;z++)t.getLevel().setBlock(BlockPos.containing(b.getX()+x,b.getY()+y,b.getZ()+z),Blocks.STONE.defaultBlockState(),2);b.face(p);b.begin(State.CHARGE_WINDUP,28);t.runAtTickTime(65,()->{t.assertTrue(b.state()==State.STUNNED&&b.duration()==50,"Thick wall not stun50: "+b.state());clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void noIdleAutoplay(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);t.assertTrue(!b.ownerActive(p.getUUID()),"Idle owner considered active attacker");b.hurt(p.damageSources().playerAttack(p),8);t.assertTrue(b.ownerActive(p.getUUID()),"Real player damage not registered");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=1600) public static void realRetreatAnd55Seconds(GameTestHelper t){var p=player(t);var b=boss(t,p);b.begin(State.STUNNED,10000);var h=hero(t,p,b);h.setHealth(42);t.runAtTickTime(35,()->t.assertTrue(h.recovering()&&h.getTarget()==null,"No retreat at42"));t.runAtTickTime(500,()->{t.assertTrue(!h.returned&&h.getHealth()<140,"Instant heal/early return");t.assertTrue(h.position().distanceToSqr(b.origin)>=24*24,"Recovery inside boss radius: "+h.state()+" "+h.position());});t.runAtTickTime(1450,()->{t.assertTrue(h.returned&&h.getHealth()>=140,"55sec recovery did not return: "+h.state()+" "+h.getHealth());clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void arenaDoesNotOverwrite(GameTestHelper t){var p=player(t);var at=BlockPos.containing(p.position().add(p.getLookAngle().multiply(36,0,36)));t.getLevel().setBlock(at,Blocks.CHEST.defaultBlockState(),2);t.assertTrue(!BogatyrArena.create(p),"Arena overwrote an occupied site");t.assertTrue(t.getLevel().getBlockState(at).is(Blocks.CHEST),"Chest deleted by arena preflight");clean(p);t.succeed();}
}
